mapper.select:
SELECT *
FROM games
WHERE game_datetime::DATE = #{gameDate}
AND (home_team = #{team, typeHandler=com.ssafy.ticket_backend.handler.BaseballTeamsTypeHandler}
OR away_team = #{team, typeHandler=com.ssafy.ticket_backend.handler.BaseballTeamsTypeHandler})

SELECT EXISTS (
SELECT 1
FROM waitlists
WHERE user_id = #{userId}
AND game_id = #{gameId}
)

SELECT EXISTS (
SELECT 1
FROM group_waitlists
WHERE user_id = #{userId}
AND game_id = #{gameId}
)

SELECT *
FROM waitlists
WHERE user_id = #{userId}
AND game_id = #{gameId}

mapper.delete:
DELETE FROM waitlists
WHERE user_id = #{userId}
AND game_id = #{gameId}

DELETE FROM group_waitlists
WHERE user_id = #{userId}
AND game_id = #{gameId}
AND number_of_people = #{numberOfPeople}

mapper.update:
UPDATE waitlists
SET waitlist_status = 'CANCEL_WAITING'
WHERE user_id = #{userId}
AND game_id = #{gameId}
